#include<stdio.h>
#define K(A,B) (A>B?B:A)

int a[1300], ac;

void f() {
    a[0] = 2;
    ac = 1;
    for(int i=3; i<=111; i+=2) {
        int c = 0;
        for(int j=3; j*j<=i; j++) {
            if(i % j == 0) {
                c = 1;
                break;
            }
        }
        if(c == 1) continue;
        a[ac++] = i;
    }
}
int main()
{
    int t, p, v = 0;
    f();
    scanf("%d", &t);
    while(t--) {
        int n;
        scanf("%d", &n);
        for(int i=0; i<ac; i++) {
            if(a[i] == n) {
                v += 0;
                break;
            }
            if(a[i] < n && n < a[i+1]) {
                v += K(a[i+1]-n, n-a[i]);
            }
        }
    }
    printf("%d", v);
    return 0;
}

