int main()
{
    int n, m, a[20];
    int s = 0;
    scanf("%d %d", &n, &m);
    for(int i=0; i<n; i++) {
        scanf("%d", &a[i]);
        s += a[i];
    }

    int l = 0, r = s;
    int ans = -1;
    while(l <= r) {
        int c = (l + r) / 2;
        int cnt = 1, t = 0, flg = 0;
        for(int i=0; i<n; i++) {
            if(t + a[i] <= c) {
                t += a[i];
            } else {
                if(a[i] <= c) {
                    t = a[i];
                    cnt++;
                } else {
                    flg = 1;
                    break;
                }
            }
        }
        if(flg || cnt > m) {
            l = c + 1;
        } else {
            r = c - 1;
            ans = c;
        }
    }
    printf("%d", ans);
    return 0;
}

